spec_raw:
{
  "cleaner": {
    "params": {
      "drop_if_constant": {
        "choice": [false, true]
      }
    }
  },
  "vectorizer": {
    "slots": {
      "numeric": ["sklearn.preprocessing.Passthrough"]
    }
  },
  "scoped_encodings": [
    {
      "name": "skewed_count_transform",
      "cols": ["total_rooms", "total_bedrooms", "population", "households", "median_income"],
      "options": [
        {
          "name": "sklearn.preprocessing.PowerTransformer",
          "params": {
            "standardize": {
              "choice": [false, true]
            }
          }
        }
      ],
      "position": "pre_encode",
      "additive": false
    }
  ],
  "stages": [
    {
      "name": "feature_eng",
      "options": [
        "skip",
        {
          "name": "sklearn.preprocessing.PolynomialFeatures",
          "params": {
            "degree": {
              "int": [2, 3]
            },
            "interaction_only": {
              "choice": [false, true]
            },
            "include_bias": {
              "choice": [false]
            }
          }
        }
      ]
    },
    {
      "name": "scale",
      "options": [
        "skip",
        "sklearn.preprocessing.StandardScaler",
        "sklearn.preprocessing.RobustScaler"
      ]
    }
  ],
  "model": [
    {
      "name": "sklearn.ensemble.HistGradientBoostingRegressor",
      "prior": 0.8,
      "params": {
        "learning_rate": {
          "float": [0.01, 0.3],
          "log": true
        },
        "max_iter": {
          "int": [100, 600]
        },
        "max_depth": {
          "int": [2, 16]
        },
        "l2_regularization": {
          "float": [0.0, 1.0]
        }
      }
    },
    {
      "name": "sklearn.ensemble.RandomForestRegressor",
      "params": {
        "n_estimators": {
          "int": [100, 500]
        },
        "max_depth": {
          "int": [3, 30]
        },
        "min_samples_leaf": {
          "int": [1, 10]
        },
        "max_features": {
          "choice": ["sqrt", "log2", 1.0]
        }
      }
    },
    {
      "name": "xgboost.XGBRegressor",
      "params": {
        "n_estimators": {
          "int": [100, 500]
        },
        "learning_rate": {
          "float": [0.01, 0.3],
          "log": true
        },
        "max_depth": {
          "int": [2, 12]
        },
        "subsample": {
          "float": [0.5, 1.0]
        },
        "colsample_bytree": {
          "float": [0.5, 1.0]
        },
        "reg_lambda": {
          "float": [0.0, 5.0]
        }
      }
    },
    {
      "name": "sklearn.linear_model.Ridge",
      "params": {
        "alpha": {
          "float": [0.001, 1000.0],
          "log": true
        }
      }
    }
  ]
}
